+/**
+ * Variance per item between two days (inclusive): theoretical use from sales
+ * sold in those days against actual use (every consume movement in them).
+ */
+export function varianceReport(store, from, to) {
+  const theoretical = new Map();
+  const actual = new Map();
+  const add = (map, itemId, qty) => map.set(itemId, (map.get(itemId) ?? 0) + qty);
+  for (const s of store.data.sales ?? []) {
+    const day = dayOf(s.soldAt);
+    if (day < from || day > to) continue;
+    const dish = store.data.dishes.find((d) => d.id === s.dishId);
+    const recipe = dish && store.data.recipes.find((r) => r.id === dish.recipeId);
+    if (!recipe) continue;
+    for (const n of scaled(recipe, s.qty)) add(theoretical, n.itemId, n.qty);
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) add(actual, batch.itemId, m.qty);
+  }
+  const round3 = (n) => Math.round(n * 1000) / 1000;
+  const ids = [...new Set([...theoretical.keys(), ...actual.keys()])].sort((a, b) => a - b);
+  return ids
+    .map((itemId) => {
+      const item = getItem(store, itemId);
+      const t = round3(theoretical.get(itemId) ?? 0);
+      const a = round3(actual.get(itemId) ?? 0);
+      return { itemId, name: item.name, unit: item.unit, theoretical: t, actual: a, difference: round3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
